"""Evergreen, mindset-first topic blueprints for The Finance Campus.

These topics begin with human money behaviours and beliefs, not financial headlines.
The linked official sources are research checks, not prompts to publish news summaries.
"""
from __future__ import annotations

from typing import Any

MINDSET_TOPIC_BLUEPRINTS: list[dict[str, Any]] = [
    {"slug":"looking-rich-vs-being-secure","title":"Looking rich can keep you financially stuck","category":"Financial Psychology","source":"bou_literacy","keywords":["financial","literacy"],"geo":["Uganda","East Africa"],"problem":"People can feel pressure to display success through clothes, phones, cars or expensive outings.","stakes":"When appearances take priority over financial priorities, money meant for essentials, savings or goals can disappear into comparison.","explanation":"Financial wellbeing is about resilience and choices, not how wealthy someone appears. Spending decisions should reflect personal priorities rather than pressure to impress others.","action":"Before your next status purchase, ask whether you would still want it if nobody else could see it."},
    {"slug":"income-up-spending-up","title":"Why earning more does not always make you wealthier","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","spending"],"geo":["global","Uganda","East Africa"],"problem":"When income rises, people often upgrade several parts of their lifestyle without deciding what the extra money should achieve.","stakes":"If every increase in income is absorbed by new spending, financial pressure can remain even while earnings grow.","explanation":"Lifestyle inflation happens when spending rises alongside income. Choosing priorities before upgrading can help turn some additional income into stability and progress.","action":"When income increases, decide in advance how much will support essentials, future goals and optional lifestyle upgrades."},
    {"slug":"emotional-spending","title":"Are you buying what you need or buying how you want to feel?","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["spending","financial"],"geo":["global","Uganda","East Africa"],"problem":"Stress, boredom, sadness or excitement can trigger purchases that feel comforting in the moment.","stakes":"Repeated emotional spending can leave less money for priorities and may create regret or financial anxiety later.","explanation":"Not every purchase is purely practical. Recognising the emotion behind a spending urge creates a chance to choose deliberately rather than react automatically.","action":"Before a non-essential purchase, name the feeling you are responding to and give yourself time to decide."},
    {"slug":"comparison-trap","title":"The money comparison trap: someone else's lifestyle is not your budget","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"Seeing friends, relatives or online personalities spend can make an ordinary life feel inadequate.","stakes":"Copying spending you cannot comfortably afford can create debt, conflict and pressure that are invisible to everyone watching.","explanation":"People have different incomes, obligations, support systems and debts. A visible lifestyle does not reveal someone's full financial position.","action":"Choose one personal financial priority and measure progress against your own starting point, not another person's display."},
    {"slug":"pay-yourself-later-myth","title":"Why waiting until you have more money to start saving can keep you waiting","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["saving","emergency"],"geo":["global","Uganda","East Africa"],"problem":"People may postpone saving because the amount they can set aside today feels too small to matter.","stakes":"Repeated postponement can leave every unexpected cost competing with money needed for daily essentials.","explanation":"A saving habit is built through consistency and a realistic amount, not by waiting for a perfect income or a perfect month.","action":"Choose a small contribution that does not endanger essentials and repeat it on a schedule you can maintain."},
    {"slug":"money-avoidance","title":"The cost of avoiding your money problems","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","decisions"],"geo":["global","Uganda","East Africa"],"problem":"Opening bills, checking balances or listing debts can feel frightening, so people sometimes avoid looking.","stakes":"Avoidance can allow due dates, fees and uncertainty to pile up, making the problem feel even larger.","explanation":"Knowing the situation does not solve everything, but it gives you a starting point for choosing what needs attention first.","action":"Set a ten-minute timer, gather the facts without judging yourself, and write down just the next issue to address."},
    {"slug":"small-leaks-big-pressure","title":"Small spending habits can quietly take control of your money","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["spending","budget"],"geo":["global","Uganda","East Africa"],"problem":"Frequent small purchases can feel harmless because each one seems affordable on its own.","stakes":"When repeated without awareness, they can crowd out priorities and leave a person wondering where the money went.","explanation":"A spending pattern matters more than any single small purchase. Tracking behaviour helps reveal which habits are worth changing.","action":"Record every small discretionary purchase for seven days and identify one pattern you want to change."},
    {"slug":"debt-as-false-relief","title":"When borrowing feels like relief but becomes another burden","category":"Debt and Loans","source":"bou_literacy","keywords":["credit","financial"],"geo":["Uganda","East Africa"],"problem":"Borrowing can feel like an immediate solution when income cannot cover today's needs or wants.","stakes":"If the reason for the shortfall remains unchanged, repayments can make future months even tighter.","explanation":"A loan moves money across time; it does not create extra income. Understanding the reason for borrowing and the full repayment obligation matters before deciding.","action":"Before borrowing, write down what problem the loan solves, what it will cost in total and how repayments fit alongside essentials."},
    {"slug":"one-more-loan-cycle","title":"The dangerous cycle of borrowing to feel financially okay","category":"Debt and Loans","source":"bou_literacy","keywords":["debt","loan"],"geo":["Uganda","East Africa"],"problem":"A person under pressure may take a new loan to cover an old payment or restore spending money.","stakes":"Repeated borrowing can postpone the underlying problem while increasing obligations and stress.","explanation":"When new debt is needed to service existing debt, it is a signal to pause and review the full situation rather than automatically borrow again.","action":"List all current obligations and speak with the lender or a qualified support service before taking another loan."},
    {"slug":"money-boundaries-family-pressure","title":"How to say no when family and friends expect your money","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","financial"],"geo":["global","Uganda","East Africa"],"problem":"Requests for help can be emotionally difficult, especially when they come from people you care about.","stakes":"Giving beyond your means can put rent, food, school costs or your own dependants at risk and create resentment.","explanation":"Generosity and financial boundaries can coexist. A clear limit helps you support others without making promises your finances cannot sustain.","action":"Decide what support you can genuinely afford before a request arrives, and practise explaining that limit respectfully."},
    {"slug":"instant-gratification","title":"Why choosing comfort today can cost you choices tomorrow","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"Immediate rewards can feel more real than a future goal that is months or years away.","stakes":"When every spare amount is spent immediately, longer-term goals may never receive consistent attention.","explanation":"Delayed gratification is the ability to balance today's wants with tomorrow's priorities. It is not about never enjoying money; it is about choosing intentionally.","action":"Pick one goal that matters to you and move a small amount toward it before spending on optional wants."},
    {"slug":"no-plan-no-direction","title":"If you do not give your money a direction, it will find one","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["budget","goals"],"geo":["global","Uganda","East Africa"],"problem":"Without a plan, spending decisions are often made one moment at a time.","stakes":"Urgent requests and tempting purchases can consume money before important obligations and goals are covered.","explanation":"A simple spending plan gives income a purpose before it is spent. It can be flexible and should reflect real circumstances.","action":"Before your next pay or business income arrives, write down the three most important jobs that money needs to do."},
    {"slug":"shame-keeps-you-stuck","title":"Money shame makes it harder to make a fresh start","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","goals"],"geo":["global","Uganda","East Africa"],"problem":"People may hide money mistakes because they fear judgement from family, friends or themselves.","stakes":"Shame can delay asking questions, seeking support or taking the first practical step toward change.","explanation":"A financial mistake is information about a decision or circumstance, not a permanent identity. Honest review is more useful than self-punishment.","action":"Write down one money lesson from the past without insulting yourself, then choose one different action for next time."},
    {"slug":"scarcity-and-short-term-thinking","title":"Why financial pressure can make tomorrow harder to think about","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","decisions"],"geo":["global","Uganda","East Africa"],"problem":"When money is constantly tight, immediate needs can consume nearly all attention.","stakes":"Long-term planning may feel impossible, even when small protective steps could reduce future pressure.","explanation":"Scarcity and uncertainty can narrow the choices people feel able to consider. Advice must respect real constraints rather than blame people for them.","action":"Focus on one manageable decision within your control this week; do not measure yourself against someone with different resources."},
    {"slug":"irregular-income-no-routine","title":"How to manage money when payday is never predictable","category":"Budgeting and Money Management","source":"cfpb_toolkit","keywords":["income","cash"],"geo":["global","Uganda","East Africa"],"problem":"Freelancers, traders and casual workers may not know exactly when or how much money will arrive.","stakes":"A fixed monthly routine may fail when income changes, leading to avoidable shortages or rushed decisions.","explanation":"A flexible system can prioritise essentials, track upcoming obligations and make saving responsive to actual cash flow.","action":"Write down essential costs and due dates, then decide how each incoming payment will be divided before optional spending."},
    {"slug":"emergency-is-not-unlucky","title":"An emergency fund is not pessimism; it is preparation","category":"Saving and Emergency Funds","source":"cfpb_emergency","keywords":["emergency","saving"],"geo":["global","Uganda","East Africa"],"problem":"Preparing for setbacks can feel unnecessary when everything is currently going well.","stakes":"Without a buffer, an ordinary disruption can force difficult trade-offs or borrowing at the worst moment.","explanation":"Emergency savings are a practical form of self-protection, not a prediction that something bad will happen.","action":"Name one realistic disruption that could affect your household and decide what first small preparation is possible."},
    {"slug":"financial-success-is-not-speed","title":"You do not need to get rich quickly to make financial progress","category":"Wealth Creation","source":"sec_investor","keywords":["investing","risk"],"geo":["global"],"problem":"Stories of sudden wealth can make steady progress feel boring or inadequate.","stakes":"Chasing speed can make people more vulnerable to unrealistic promises, reckless risks or scams.","explanation":"Sustainable financial progress is usually built through informed choices, risk awareness, patience and consistency; no approach guarantees wealth.","action":"Set one realistic financial goal and identify a repeatable step that supports it without relying on a promise of quick returns."},
    {"slug":"money-goals-need-identity","title":"Become the person who follows through on money goals","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["goals","saving"],"geo":["global","Uganda","East Africa"],"problem":"People often set ambitious financial goals but rely only on motivation to keep going.","stakes":"When motivation fades, the goal can disappear from everyday decisions.","explanation":"A repeatable routine, clear reminder and manageable action can make a goal easier to maintain than relying on willpower alone.","action":"Attach one small money action to an existing weekly routine and review it at the same time each week."},
    {"slug":"financial-independence-starts-with-awareness","title":"Financial independence starts before you become wealthy","category":"Wealth Creation","source":"cfpb_toolkit","keywords":["financial","goals"],"geo":["global","Uganda","East Africa"],"problem":"Financial independence can seem like a distant destination reserved for people with high incomes.","stakes":"If it feels unreachable, people may ignore the smaller choices that can improve their current level of control.","explanation":"Greater financial independence begins with understanding obligations, making deliberate choices and gradually building options; the path differs by circumstance.","action":"Identify one recurring expense, obligation or habit you can understand better this week and decide whether it still serves your priorities."},
    {"slug":"do-not-confuse-income-with-worth","title":"Your income does not determine your worth","category":"Financial Psychology","source":"cfpb_toolkit","keywords":["financial","wellbeing"],"geo":["global","Uganda","East Africa"],"problem":"People may judge their value by salary, possessions or how quickly they appear to progress.","stakes":"That pressure can lead to overwork, unhealthy comparison and spending decisions made to prove personal worth.","explanation":"Income is a financial resource, not a measure of human value. A healthy money plan should serve a person's real needs and values.","action":"Write down what financial stability would mean in your own life, without using another person's lifestyle as the benchmark."},
]

